operations.new:
private suspend fun findFilesystemForSession(session: Session): Filesystem? {
    val cachedFilesystem = filesystems.find { filesystem ->
        filesystem.id == session.filesystemId
    }
    if (cachedFilesystem != null) return cachedFilesystem

    return withContext(Dispatchers.IO) {
        filesystemDao.getFilesystemById(session.filesystemId)
    }
}

private suspend fun handleSessionSelected(session: Session) {
    if (activeSessions.isNotEmpty()) {
        if (activeSessions.contains(session)) {
            state.postValue(SessionIsRestartable(session))
            return
        }

        state.postValue(SingleSessionSupported)
        return
    }

    val filesystem = findFilesystemForSession(session)
    if (filesystem == null) {
        state.postValue(SessionFilesystemUnavailable(session))
        return
    }
    state.postValue(SessionIsReadyForPreparation(session, filesystem))
}
